style.css:
@-moz-document domain("chat.google.com") {
/* NỀN CHÍNH */
body {
    background: #fff0f6 !important;
    color: #ff5c9a !important;
    font-family: "Quicksand", sans-serif !important;
}

/* SIDEBAR */
[role="navigation"] {
    background: #ffd6e7 !important;
    border-right: 2px solid #ffb6d5 !important;
}

/* KHUNG CHAT */
[role="main"] {
    background: #fff5fa !important;
    border-radius: 20px !important;
}

/* Ô TIN NHẮN */
div[aria-label="Message"] {
    background: #ffcce0 !important;
    border-radius: 20px !important;
    color: #ff4f8b !important;
}

/* NÚT */
button {
    background: #ff9fc5 !important;
    border-radius: 15px !important;
    color: white !important;
    border: none !important;
}

/* HOVER */
button:hover {
    background: #ff7eb3 !important;
}

/* THANH TÌM KIẾM */
input {
    background: #ffe6f0 !important;
    border-radius: 20px !important;
    color: #ff5c9a !important;
    border: 1px solid #ffb6d5 !important;
}

/* BONG BÓNG TIN NHẮN */
.message {
    background: #ffd9e8 !important;
    border-radius: 18px !important;
    padding: 8px !important;
}

/* ICON */
svg {
    fill: #ff6fa3 !important;
}

/* SCROLLBAR */
::-webkit-scrollbar-thumb {
    background: #ff9fc5 !important;
    border-radius: 10px;
}
}
